def check_case1(y, z):
    # Case 1: x=1. Equation: 1 + y^3 + z^3 = y^2*z^2
    return 1 + y**3 + z**3 == y**2 * z**2

# Search for y up to 4, z up to 10 (since y <= z)
solutions_case1 = []
for y in range(1, 5):
    for z in range(y, 11):
        if check_case1(y, z):
            solutions_case1.append((1, y, z))

print("Case 1 Solutions (1 <= y <= z <= 10):", solutions_case1)

def check_case2(x, z):
    # Case 2: x=y. Equation: 2*x^3 + z^3 = x^4*z^2
    return 2 * x**3 + z**3 == x**4 * z**2

# Search for x up to 3, z up to 10 (since x <= z)
solutions_case2 = []
for x in range(1, 4):
    for z in range(x, 11):
        if check_case2(x, z):
            solutions_case2.append((x, x, z))

print("Case 2 Solutions (x <= z <= 10):", solutions_case2)

def check_solution(x, y, z):
    # Equation: x^3 + y^3 + z^3 = x^2*y^2*z^2
    lhs = x**3 + y**3 + z**3
    rhs = x**2 * y**2 * z**2
    return lhs == rhs

solutions = []
